import java.io.*;import java.nio.file.*;import org.springframework.boot.loader.tools.*;public class Repackage25 { public static void main(String[] args)throws Exception {var source=new File(args[0]);var destination=new File(args[1]);if(destination.exists())throw new IllegalStateException("NEW_ARTIFACT_REQUIRED");var paths=Files.readAllLines(Path.of(args[2]));var p=new Repackager(source);p.setMainClass("cn.xinji.agentplatform.security.product.ProductConsultationApplication");p.repackage(destination,callback->{for(String file:paths)callback.library(new Library(new File(file),LibraryScope.COMPILE));});System.out.println("NEW_CONSULTATION_PACKAGE_WRITTEN");}}
